<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('POST');apiCsrf();$uid=apiAuth();$in=apiInput();$qid=apiId($in['quotation_id']??0);$db=apiDb();$s=$db->prepare('SELECT id FROM quotation_requests WHERE id=? AND (buyer_id=? OR supplier_id IN (SELECT id FROM suppliers WHERE user_id=?))');$s->execute([$qid,$uid,$uid]);if(!$s->fetch())apiError('Quotation not found',404);$s=$db->prepare('INSERT INTO negotiations(quotation_request_id,status) VALUES(?,"open")');$s->execute([$qid]);apiResponse(['id'=>(int)$db->lastInsertId()],201);